-- Details of the current session
SELECT VERSION() AS server_version,
       CURRENT_USER() AS login,
       DATABASE() AS current_db;

-- Warnings produced by the previous statement
SHOW WARNINGS;

CREATE DATABASE IF NOT EXISTS inventory
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_0900_ai_ci;

USE inventory;

SHOW DATABASES;
SHOW TABLES;
SELECT DATABASE() AS current_db;

-- Add, change and remove columns
ALTER TABLE products ADD COLUMN barcode VARCHAR(64) NULL AFTER sku;
ALTER TABLE products MODIFY COLUMN notes VARCHAR(500) NULL;
ALTER TABLE products ADD INDEX idx_products_barcode (barcode);
ALTER TABLE products DROP INDEX idx_products_barcode;

-- Remove objects; IF EXISTS keeps the script repeatable
DROP TABLE IF EXISTS scratch_notes;
DROP DATABASE IF EXISTS old_inventory;

INSERT INTO products (sku, name, price_cents, stock)
VALUES ('KB-1000', 'Mechanical Keyboard', 12900, 12);

-- Several rows in one statement
INSERT INTO products (sku, name, price_cents, stock) VALUES
  ('MS-2000', 'Wireless Mouse', 4500, 30),
  ('HD-3000', 'USB-C Hub', 8900, 8);

-- Skip rows that would duplicate a UNIQUE key
INSERT IGNORE INTO products (sku, name, price_cents)
VALUES ('KB-1000', 'Mechanical Keyboard', 12900);

SELECT LAST_INSERT_ID() AS last_generated_id;

SELECT id, sku, name, price_cents FROM products;

-- Compute values and give the result a name
SELECT name,
       price_cents / 100 AS price_dollars,
       stock * price_cents AS inventory_value_cents
FROM products;

-- Build a single display string
SELECT CONCAT(name, ' (', sku, ')') AS label, stock
FROM products;

-- Remove duplicate values from the result
SELECT DISTINCT stock FROM products;

DELETE FROM order_items
WHERE order_id = 42;

DELETE FROM orders
WHERE status = 'cancelled'
  AND placed_at < '2025-01-01';

-- Delete everything but keep the table and its indexes
TRUNCATE TABLE order_items;

-- Check the row count before deleting a wide condition
SELECT COUNT(*) FROM orders WHERE status = 'cancelled';

-- Speed up lookups and sorts on a column
CREATE INDEX idx_products_name ON products (name);

-- Composite index: usable by status alone, or by status and placed_at
CREATE INDEX idx_orders_status_placed ON orders (status, placed_at);

-- Descending index (MySQL 8.0+)
CREATE INDEX idx_products_price_desc ON products (price_cents DESC);

-- Full-text index for word searches
CREATE FULLTEXT INDEX ft_products_name ON products (name);

-- Inspect the indexes of a table
SHOW INDEX FROM products;

-- Remove one index
DROP INDEX idx_products_name ON products;

-- Rebuild table statistics used by the optimizer
ANALYZE TABLE products;

-- Show the statement that would recreate the table
SHOW CREATE TABLE products;

START TRANSACTION;

UPDATE products
SET stock = stock - 2
WHERE id = 7;

INSERT INTO orders (customer_id, status, total_cents)
VALUES (3, 'pending', 17800);

COMMIT;

-- Undo every statement since START TRANSACTION
START TRANSACTION;
DELETE FROM orders WHERE id = 91;
ROLLBACK;

-- Keep part of the work with a savepoint
START TRANSACTION;
UPDATE products SET stock = stock - 1 WHERE id = 7;
SAVEPOINT after_stock;

INSERT INTO order_items (order_id, product_id, quantity, unit_price_cents)
VALUES (91, 7, 1, 8900);

ROLLBACK TO SAVEPOINT after_stock;
COMMIT;

-- Isolation level for the rest of the session
SET SESSION TRANSACTION ISOLATION LEVEL READ COMMITTED;

CREATE USER 'app_user'@'localhost' IDENTIFIED BY 'S3cure-Passw0rd!';
CREATE USER 'report'@'10.0.0.%' IDENTIFIED BY 'R3port-Passw0rd!';

-- Grant only the statements the application needs
GRANT SELECT, INSERT, UPDATE, DELETE ON inventory.* TO 'app_user'@'localhost';
GRANT SELECT ON inventory.orders TO 'report'@'10.0.0.%';

-- Review what an account can do
SHOW GRANTS FOR 'app_user'@'localhost';

REVOKE DELETE ON inventory.* FROM 'app_user'@'localhost';

ALTER USER 'app_user'@'localhost' IDENTIFIED BY 'N3w-Passw0rd!';
DROP USER 'report'@'10.0.0.%';

-- Roles (MySQL 8.0+)
CREATE ROLE 'read_only';
GRANT SELECT ON inventory.* TO 'read_only';
GRANT 'read_only' TO 'report'@'10.0.0.%';
SET DEFAULT ROLE 'read_only' TO 'report'@'10.0.0.%';

-- Actually run the statement and report real timings (MySQL 8.0.18+)
EXPLAIN ANALYZE
SELECT id FROM orders WHERE status = 'pending';

-- Record statements slower than one second
SET GLOBAL slow_query_log = 'ON';
SET GLOBAL long_query_time = 1;
SHOW VARIABLES LIKE 'slow_query_log_file';

-- Refresh the statistics the optimizer reads
ANALYZE TABLE orders;
